package PRACTISE;

public class StringExamples {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
     String x = "Suraiya Banu" ;
     String y = " Will become automation Engineer Soon";
     System.out.println("Length of the name : "+ x.length());
     System.out.println("Name in \'Caps\' : " + x.toUpperCase());
     System.out.println("Name in \"Lower\" : " + x.toLowerCase());
     System.out.println("B is @ place of : " + x.indexOf('B'));
     System.out.println(x.concat(y));
     
}
}